<div class="top"><div><div class="eyebrow">Verenigingsplatform</div><h1>Onboarding hervatten</h1><p class="muted">Eén vaste, hervatbare route van basisprovisioning naar een actieve vereniging. Wachtwoorden en providercredentials blijven buiten de browser.</p></div><div class="actions"><a class="btn" href="/?section=onboarding">← Terug naar beheerconsole</a><span class="badge"><?=hob(control58RoleLabel(cpSuiteRole()))?></span></div></div>
<?php if($melding!==''):?><div class="notice ok"><?=hob($melding)?></div><?php endif;?><?php if($fout!==''):?><div class="notice err"><?=hob($fout)?></div><?php endif;?><?php if(!$canMutate):?><div class="notice info">Je platformrol is alleen-lezen. Je kunt de onboardingstatus bekijken, maar niet hervatten.</div><?php endif;?>
<div class="grid"><?php if(!$tenants):?><div class="empty">Er zijn geen verenigingen met open onboarding.</div><?php endif;?><?php foreach($tenants as$t):$key=(string)$t['tenant_key'];$name=(string)($t['name']??$key);$ob=cpSuiteOnboarding($t);$steps=$ob['steps'];$adminDone=false;foreach($steps as$s)if(($s['key']??'')==='admin')$adminDone=($s['done']??false)===true;$profile=is_array($t['dns_profile']??null)?$t['dns_profile']:null;$strategy=(string)($profile['strategy']??'direct');$ipv4=implode(',',array_values((array)($profile['ipv4']??[])));$ipv6=implode(',',array_values((array)($profile['ipv6']??[])));$cname=(string)($profile['cname']??'');$host=(string)($t['canonical_host']??'');?>
